package stirling.software.common.service;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

import java.lang.reflect.Field;
import java.util.Collection;
import java.util.Spliterator;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

/**
 * Tests for {@link JobQueue} concurrency behavior.
 * Verifies that cancelJob() properly synchronizes on queueLock when accessing
 * shared state (jobQueue, currentQueueSize) that is also accessed by
 * updateQueueCapacity() and processQueue().
 */
class JobQueueConcurrencyTest {

    private ResourceMonitor resourceMonitor;

    @BeforeEach
    void setUp() {
        resourceMonitor = Mockito.mock(ResourceMonitor.class);
        when(resourceMonitor.calculateDynamicQueueCapacity(anyInt(), anyInt()))
                .thenReturn(100);
        AtomicReference<ResourceMonitor.ResourceStatus> statusRef =
                new AtomicReference<>(ResourceMonitor.ResourceStatus.OK);
        when(resourceMonitor.getCurrentStatus()).thenReturn(statusRef);
    }

    /**
     * Demonstrates the TOCTOU race between cancelJob() and updateQueueCapacity().
     *
     * cancelJob() reads jobQueue and calls remove() WITHOUT holding queueLock.
     * updateQueueCapacity() drains jobQueue to a NEW queue and swaps it WHILE
     * holding queueLock.
     *
     * Race sequence:
     * 1. cancelJob: job = jobMap.remove(jobId)  [success]
     * 2. cancelJob: reads jobQueue -> Q1 (stale ref after swap)
     * 3. Meanwhile: drain Q1 -> Q2, swap jobQueue = Q2
     * 4. cancelJob: Q1.remove(job) -> FALSE (job was moved to Q2!)
     * 5. Result: cancelJob returns TRUE but job is STILL in Q2!
     *
     * This test forces the race by making cancelJob pause between reading
     * jobQueue and calling remove() on it, using a BlockingQueue proxy that
     * blocks on remove(Object). While paused, we drain the queue and swap
     * jobQueue to a new queue.
     */
    @Test
    void cancelJob_raceWithUpdateQueueCapacity_jobMustBeRemovedFromCurrentQueue()
            throws Exception {
        when(resourceMonitor.calculateDynamicQueueCapacity(anyInt(), anyInt()))
                .thenReturn(100);

        JobQueue jq = new JobQueue(resourceMonitor);
        String jobId = "race-demo-job";

        // Submit a job — it goes into the initial queue
        jq.queueJob(jobId, 10, () -> "result", 60000);
        Thread.sleep(10);

        // Get the initial queue Q1
        LinkedBlockingQueue<Object> q1 = (LinkedBlockingQueue<Object>) getJobQueue(jq);
        assertEquals(1, q1.size());

        // Create a BlockingQueue proxy that wraps Q1 and blocks on remove(Object o).
        // cancelJob will hold a local reference to this proxy and call remove(job) on it.
        CountDownLatch removeCalled = new CountDownLatch(1);
        CountDownLatch allowRemove = new CountDownLatch(1);
        BlockingQueue<Object> proxyQ1 = new BlockingQueueProxy<>(
                q1, removeCalled, allowRemove);

        // Replace jobQueue with the proxy
        setJobQueue(jq, proxyQ1);

        // Start cancelJob in a thread — it will read jobQueue (proxyQ1) and
        // call proxyQ1.remove(Object) which will block
        AtomicBoolean cancelResult = new AtomicBoolean(false);
        CountDownLatch cancelDone = new CountDownLatch(1);

        ExecutorService executor = Executors.newVirtualThreadPerTaskExecutor();
        executor.submit(() -> {
            try {
                cancelResult.set(jq.cancelJob(jobId));
            } catch (Exception e) {
            } finally {
                cancelDone.countDown();
            }
        });

        // Wait for cancelJob to reach proxy.remove(Object) — it's now BLOCKED
        assertTrue(removeCalled.await(5, TimeUnit.SECONDS),
                "cancelJob should have called remove()");

        // === RACE WINDOW ===
        // cancelJob is blocked in proxy.remove(Object).
        // Now we manually simulate what updateQueueCapacity does:
        // drain the OLD queue to a NEW queue and swap jobQueue.

        // Create new queue Q2
        LinkedBlockingQueue<Object> q2 = new LinkedBlockingQueue<>(200);

        // Drain Q1 into Q2 (this is what updateQueueCapacity.drainTo does)
        q1.drainTo(q2);

        // Verify job moved to Q2
        assertEquals(0, q1.size(), "Q1 should be empty after drain");
        assertEquals(1, q2.size(), "Job should be in Q2 after drain");

        // Swap jobQueue to Q2 (simulating updateQueueCapacity's: jobQueue = newQueue)
        Object queueLock = getQueueLock(jq);
        synchronized (queueLock) {
            setJobQueue(jq, q2);
        }

        // Now release the proxy's remove(Object) call
        allowRemove.countDown();
        assertTrue(cancelDone.await(5, TimeUnit.SECONDS));

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);

        // cancelJob returned true (job was found in jobMap and removed from proxyQ1/Q1)
        assertTrue(cancelResult.get(), "cancelJob should return true — job was found in map");

        // CRITICAL ASSERTION: the job should NOT be in the CURRENT queue (Q2).
        // The BUG: cancelJob removed from Q1 (stale proxy), but the job was
        // moved to Q2 by updateQueueCapacity. So the job is STILL in Q2!
        boolean found = jobFoundInQueue(q2, jobId);

        assertFalse(found,
                "BUG: cancelJob returned true but job is still in the current queue (Q2). "
                        + "cancelJob removed from the stale Q1 reference because it did not "
                        + "synchronize on queueLock while accessing jobQueue.");
    }

    private BlockingQueue<?> getJobQueue(JobQueue jq) throws Exception {
        Field field = JobQueue.class.getDeclaredField("jobQueue");
        field.setAccessible(true);
        return (BlockingQueue<?>) field.get(jq);
    }

    private void setJobQueue(JobQueue jq, BlockingQueue<?> queue) throws Exception {
        Field field = JobQueue.class.getDeclaredField("jobQueue");
        field.setAccessible(true);
        field.set(jq, queue);
    }

    private Object getQueueLock(JobQueue jq) throws Exception {
        Field field = JobQueue.class.getDeclaredField("queueLock");
        field.setAccessible(true);
        return field.get(jq);
    }

    private boolean jobFoundInQueue(BlockingQueue<?> queue, String jobId) {
        for (Object item : queue) {
            if (item != null) {
                try {
                    Field idField = item.getClass().getDeclaredField("jobId");
                    idField.setAccessible(true);
                    if (jobId.equals(idField.get(item))) {
                        return true;
                    }
                } catch (Exception e) {
                    // ignore
                }
            }
        }
        return false;
    }

    /**
     * A BlockingQueue proxy that delegates to a wrapped queue but blocks on a
     * latch during remove(Object o) calls. This allows us to force the race window
     * where cancelJob holds a reference to an old queue while updateQueueCapacity
     * swaps the queue.
     */
    private static class BlockingQueueProxy<E> implements BlockingQueue<E> {
        private final BlockingQueue<E> delegate;
        private final CountDownLatch removeCalled;
        private final CountDownLatch allowRemove;

        BlockingQueueProxy(LinkedBlockingQueue<E> delegate, CountDownLatch removeCalled,
                CountDownLatch allowRemove) {
            this.delegate = delegate;
            this.removeCalled = removeCalled;
            this.allowRemove = allowRemove;
        }

        @Override
        public E remove() { return delegate.remove(); }

        @Override
        public boolean remove(Object o) {
            removeCalled.countDown();
            try {
                allowRemove.await(10, TimeUnit.SECONDS);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            return delegate.remove(o);
        }

        @Override public boolean add(E e) { return delegate.add(e); }
        @Override public boolean offer(E e) { return delegate.offer(e); }
        @Override public void put(E e) throws InterruptedException { delegate.put(e); }
        @Override public boolean offer(E e, long timeout, TimeUnit unit) throws InterruptedException {
            return delegate.offer(e, timeout, unit);
        }
        @Override public E take() throws InterruptedException { return delegate.take(); }
        @Override public E poll(long timeout, TimeUnit unit) throws InterruptedException {
            return delegate.poll(timeout, unit);
        }
        @Override public E poll() { return delegate.poll(); }
        @Override public E element() { return delegate.element(); }
        @Override public E peek() { return delegate.peek(); }
        @Override public int remainingCapacity() { return delegate.remainingCapacity(); }
        @Override public int drainTo(Collection<? super E> c) { return delegate.drainTo(c); }
        @Override public int drainTo(Collection<? super E> c, int maxElements) {
            return delegate.drainTo(c, maxElements);
        }
        @Override public boolean isEmpty() { return delegate.isEmpty(); }
        @Override public boolean contains(Object o) { return delegate.contains(o); }
        @Override public boolean containsAll(Collection<?> c) { return delegate.containsAll(c); }
        @Override public java.util.Iterator<E> iterator() { return delegate.iterator(); }
        @Override public int size() { return delegate.size(); }
        @Override public Object[] toArray() { return delegate.toArray(); }
        @Override public <T> T[] toArray(T[] a) { return delegate.toArray(a); }
        @Override public boolean removeAll(Collection<?> c) { return delegate.removeAll(c); }
        @Override public boolean retainAll(Collection<?> c) { return delegate.retainAll(c); }
        @Override public boolean addAll(Collection<? extends E> c) { return delegate.addAll(c); }
        @Override public Spliterator<E> spliterator() { return delegate.spliterator(); }
        @Override public void clear() { delegate.clear(); }
        @Override public String toString() { return delegate.toString(); }
    }
}

