                        + "ALTER TABLE \"PUBLIC\".\"USERS\" ADD CONSTRAINT \"PUBLIC\".\"FKFJWS1RDRUAB2BQG7QIPOQF65R\" FOREIGN KEY(\"TEAM_ID\") REFERENCES \"PUBLIC\".\"TEAMS\"(\"TEAM_ID\") NOCHECK;      \n"
                        + "";

        Path script = Files.createTempFile("backup", ".sql");
        Files.writeString(script, sqlContent);

        boolean result = databaseService.importDatabaseFromUI(script);
        assertThat(result).isTrue();
    }

    @Test
    void deleteOldestBackup_shouldNotThrowOnShortFilename() throws Exception {
        // "backup.sql" is only 10 chars; substring(7, 10-4) = substring(7, 6) would throw
        // StringIndexOutOfBoundsException in the buggy code
        // Need 2+ elements so sort() actually invokes the comparator
        FileInfo shortFile =
                new FileInfo("backup.sql", tempDir.resolve("backup.sql").toString(), null, 0, null);
        FileInfo normalFile =
                new FileInfo(
                        "backup_202301011200.sql",
                        tempDir.resolve("backup_202301011200.sql").toString(),
                        null,
                        0,
                        null);
        java.util.List<FileInfo> list =
                new java.util.ArrayList<>(java.util.List.of(shortFile, normalFile));

        java.lang.reflect.Method method =
                DatabaseService.class.getDeclaredMethod("deleteOldestBackup", List.class);
        method.setAccessible(true);

        assertDoesNotThrow(
                () -> method.invoke(null, list),
                "deleteOldestBackup should handle short filenames gracefully without throwing StringIndexOutOfBoundsException");
    }
}

