package stirling.software.proprietary.security.controller.api;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.core.io.PathResource;
import org.springframework.core.io.Resource;
import org.springframework.http.ResponseEntity;

import stirling.software.proprietary.security.service.DatabaseService;

/**
 * Unit tests for {@link DatabaseController} that verify the downloadFile() method returns a
 * resource type that does not leak file descriptors.
 */
class DatabaseControllerDownloadFileTest {

    @TempDir Path tempDir;

    /**
     * Verifies that downloadFile() returns a PathResource (which properly manages lifecycle) rather
     * than InputStreamResource (which leaks the underlying stream).
     *
     * <p>The bug: Files.newInputStream(filePath) creates a FileInputStream that is wrapped in
     * InputStreamResource. Since InputStreamResource does NOT implement Closeable, the underlying
     * FileInputStream is never closed after Spring reads the response body, causing file descriptor
     * exhaustion under load.
     *
     * <p>The fix: use PathResource (or FileSystemResource) instead of InputStreamResource.
     */
    @Test
    void downloadFile_shouldReturnPathResourceNotInputStreamResource_toAvoidResourceLeak()
            throws IOException {
        // Given: a mock DatabaseService that returns a valid backup file path
        DatabaseService mockService = mock(DatabaseService.class);
        Path testFile = tempDir.resolve("backup_test.sql");
        Files.writeString(testFile, "-- test backup content");
        when(mockService.getBackupFilePath("backup_test.sql")).thenReturn(testFile);

        DatabaseController controller = new DatabaseController(mockService);

        // When: we call downloadFile
        ResponseEntity<?> response = controller.downloadFile("backup_test.sql");

        // Then: the response body should be a PathResource, NOT an InputStreamResource
        assertNotNull(response.getBody(), "Response body should not be null");
        Resource body = (Resource) response.getBody();
        assertInstanceOf(
                PathResource.class,
                body,
                "Response body should be PathResource to avoid resource leak, "
                        + "not InputStreamResource which leaks the underlying FileInputStream");
    }
}

