package stirling.software.proprietary.security.controller.api;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.io.InputStream;
import java.io.PrintWriter;
import java.lang.reflect.Field;
import java.nio.file.Files;
import java.nio.file.Path;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.core.io.InputStreamResource;
import org.springframework.http.ResponseEntity;

import stirling.software.proprietary.security.service.DatabaseService;

/**
 * Reproduces the file-descriptor leak in {@link DatabaseController#downloadFile(String)}.
 *
 * <p>Line 210 of DatabaseController does: {@code new
 * InputStreamResource(Files.newInputStream(filePath))}
 *
 * <p>The {@code InputStreamResource(InputStream)} constructor stores the raw stream and does NOT
 * close it after reading. Every download leaks one file descriptor.
 *
 * <p>Correct fix: use the Supplier constructor: {@code new InputStreamResource(() ->
 * Files.newInputStream(filePath))}
 */
class DatabaseControllerDownloadFileTest {

    @TempDir Path tempDir;

    /**
     * Assert that the FileInputStream created for a download IS closed after the response body is
     * read, preventing file descriptor exhaustion under load.
     */
    @Test
    void downloadFile_streamClosedAfterReading() throws Exception {
        Path backupFile = tempDir.resolve("backup_202401011200.sql");
        try (PrintWriter pw = new PrintWriter(Files.newBufferedWriter(backupFile))) {
            pw.println("-- H2 backup");
            pw.println("CREATE TABLE USERS(ID INT);");
        }
        String fileName = backupFile.getFileName().toString();

        DatabaseService databaseService = mock(DatabaseService.class);
        when(databaseService.getBackupFilePath(fileName)).thenReturn(backupFile);

        DatabaseController controller = new DatabaseController(databaseService);
        ResponseEntity<?> response = controller.downloadFile(fileName);

        assertThat(response.getStatusCode().value()).isEqualTo(200);
        assertThat(response.getBody()).isInstanceOf(InputStreamResource.class);

        InputStreamResource resource = (InputStreamResource) response.getBody();

        // Simulate the HTTP framework reading the response body
        byte[] content = resource.getContentAsByteArray();
        assertThat(content).isNotEmpty();

        // Check that the underlying FileInputStream is closed
        InputStream stream = findInputStreamField(resource);
        assertThat(stream).as("InputStreamResource must expose an InputStream field").isNotNull();

        assertThat(isClosed(stream))
                .as(
                        "FileInputStream must be closed after getContentAsByteArray() "
                                + "to prevent file descriptor leak")
                .isTrue();
    }

    /** Locate the first declared field whose value is an InputStream. */
    private InputStream findInputStreamField(Object obj) {
        for (Field f : obj.getClass().getDeclaredFields()) {
            f.setAccessible(true);
            try {
                Object val = f.get(obj);
                if (val instanceof InputStream) {
                    return (InputStream) val;
                }
            } catch (IllegalAccessException ignored) {
            }
        }
        return null;
    }

    /**
     * Return true if the {@code FileInputStream} is closed. Inspects the JDK-internal {@code
     * closed} boolean field via reflection.
     */
    private boolean isClosed(InputStream stream) {
        try {
            Field closedField = stream.getClass().getDeclaredField("closed");
            closedField.setAccessible(true);
            return (boolean) closedField.get(stream);
        } catch (NoSuchFieldException e) {
            try {
                Field fdField = stream.getClass().getDeclaredField("fd");
                fdField.setAccessible(true);
                return fdField.get(stream) == null;
            } catch (NoSuchFieldException | IllegalAccessException ex) {
                return false;
            }
        } catch (IllegalAccessException e) {
            return false;
        }
    }
}

