package stirling.software.common.cluster.inprocess;

import static org.junit.jupiter.api.Assertions.fail;

import java.time.Duration;
import java.util.Optional;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;

import org.junit.jupiter.api.RepeatedTest;
import org.junit.jupiter.api.Test;

/**
 * Tests for TOCTOU race in {@link InProcessKeyValueCache#get}.
 *
 * Between {@code ns.get(key)} and {@code e.expiry.isBefore(Instant.now())},
 * another thread can call {@code put()} with a fresh TTL, replacing the
 * expired entry. The getter then {@code ns.remove(key, e)} which fails (value
 * changed), but still returns {@code Optional.empty()} even though a valid
 * non-expired entry exists.
 */
class InProcessKeyValueCacheRaceTest {

    /**
     * Stress-test: an expired entry is repeatedly replaced by a fresh one while
     * a reader thread continuously calls get(). If the TOCTOU race hits, get()
     * returns empty even though a fresh entry exists.
     */
    @Test
    void getShouldNotReturnEmptyWhenConcurrentPutReplacesExpiredEntry() throws Exception {
        InProcessKeyValueCache cache = new InProcessKeyValueCache();
        String ns = "ns", key = "k";
        AtomicBoolean raceDetected = new AtomicBoolean(false);
        AtomicReference<String> lastFreshValue = new AtomicReference<>();

        // Run multiple rounds to increase probability of hitting the race
        int rounds = 50;
        for (int round = 0; round < rounds && !raceDetected.get(); round++) {
            // Put an expired entry
            cache.put(ns, key, "expired", Duration.ofNanos(1));
            Thread.sleep(2); // ensure expired

            // Prepare synchronization
            CountDownLatch getterDone = new CountDownLatch(1);
            CountDownLatch putterReady = new CountDownLatch(1);
            AtomicReference<Optional<String>> getResult = new AtomicReference<>();
            String freshValue = "fresh-" + round;

            Thread getter = new Thread(() -> {
                // Call get() which internally does ns.get(key), checks expiry,
                // then ns.remove(key, e) - if e was replaced, remove fails but
                // still returns empty
                getResult.set(cache.get(ns, key));
                getterDone.countDown();
            });

            Thread putter = new Thread(() -> {
                try {
                    // Let getter start reading
                    Thread.sleep(1);
                    // Replace expired entry with a fresh one
                    cache.put(ns, key, freshValue, Duration.ofHours(1));
                    lastFreshValue.set(freshValue);
                    putterReady.countDown();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            });

            putter.start();
            getter.start();

            // Wait for both threads
            getter.join(5000);
            putter.join(5000);

            // If getter returned empty AFTER putter put a fresh entry,
            // verify the entry is actually there (confirming the race)
            if (getResult.get().isEmpty() && putterReady.getCount() == 0) {
                // Putter completed - check if a fresh entry is actually in the cache
                Optional<String> verify = cache.get(ns, key);
                if (verify.isPresent()) {
                    raceDetected.set(true);
                }
            }
        }

        if (raceDetected.get()) {
            fail("TOCTOU race detected: get() returned Optional.empty() when a valid "
                    + "fresh entry (value='" + lastFreshValue.get()
                    + "') existed in the cache");
        }
    }

    /**
     * High-contention stress test using many threads to widen the race window.
     */
    @RepeatedTest(20)
    void getShouldNotReturnEmptyUnderHighContention() throws Exception {
        InProcessKeyValueCache cache = new InProcessKeyValueCache();
        String ns = "ns", key = "k";
        AtomicBoolean raceDetected = new AtomicBoolean(false);

        ExecutorService executor = Executors.newFixedThreadPool(8);

        // Put an initially expired entry
        cache.put(ns, key, "expired", Duration.ofNanos(1));
        Thread.sleep(5);

        int iterations = 10000;
        CountDownLatch ready = new CountDownLatch(8);
        CountDownLatch start = new CountDownLatch(1);

        // Multiple getter threads
        for (int t = 0; t < 4; t++) {
            executor.submit(() -> {
                ready.countDown();
                try {
                    start.await();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return;
                }
                for (int i = 0; i < iterations; i++) {
                    Optional<String> result = cache.get(ns, key);
                    if (result.isEmpty()) {
                        // Check if fresh entry exists
                        Optional<String> verify = cache.get(ns, key);
                        if (verify.isPresent()) {
                            raceDetected.set(true);
                        }
                    }
                }
            });
        }

        // Multiple putter threads
        for (int t = 0; t < 4; t++) {
            executor.submit(() -> {
                ready.countDown();
                try {
                    start.await();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return;
                }
                for (int i = 0; i < iterations; i++) {
                    // Alternate between expired and fresh entries
                    if (i % 2 == 0) {
                        cache.put(ns, key, "expired", Duration.ofNanos(1));
                    } else {
                        cache.put(ns, key, "fresh-" + i, Duration.ofHours(1));
                    }
                }
            });
        }

        ready.await();
        start.countDown();

        executor.shutdown();
        executor.awaitTermination(60, TimeUnit.SECONDS);

        if (raceDetected.get()) {
            fail("TOCTOU race detected under high contention: get() returned empty "
                    + "when valid entry existed");
        }
    }
}

