package stirling.software.proprietary.security.session;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;

import java.time.Duration;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.test.util.ReflectionTestUtils;

import stirling.software.proprietary.security.database.repository.SessionRepository;

@ExtendWith(MockitoExtension.class)
class SessionPersistentRegistryTest {

    private SessionRepository sessionRepository = mock(SessionRepository.class);
    private SessionPersistentRegistry registry;

    @org.junit.jupiter.api.BeforeEach
    void setUp() {
        registry = new SessionPersistentRegistry(sessionRepository);
    }

    @Test
    void getMaxInactiveInterval_normalDuration_returnsCorrectValue() {
        // 30 minutes = 1800 seconds
        Duration duration = Duration.ofMinutes(30);
        ReflectionTestUtils.setField(registry, "defaultMaxInactiveInterval", duration);

        int result = registry.getMaxInactiveInterval();

        assertThat(result).isEqualTo(1800);
    }

    @Test
    void getMaxInactiveInterval_largeDuration_shouldNotOverflowToNegative() {
        // 30,000 days = 2,592,000,000 seconds > Integer.MAX_VALUE (2,147,483,647)
        // The cast (int) on long will overflow and produce a negative number
        Duration duration = Duration.ofDays(30_000);
        ReflectionTestUtils.setField(registry, "defaultMaxInactiveInterval", duration);

        int result = registry.getMaxInactiveInterval();

        // 30,000 days in seconds = 2,592,000,000
